    end

    if self.RightPanel then
        local env = CfUtils.GetLuaScr(self.RightPanel,RightPanelEnvPath)
        if env then
            env:SetCallBack(Bind(self,self.CollectCallBack),Bind(self,self.CookCallBack),Bind(self,self.CookingSuccessCallBack))
            self.rightPanelEnv = env
        end
    end

    if self.TipNode then
        local env = CfUtils.GetLuaScr(self.TipNode,PriceTipEnvPath)
        if env then
            self.tipsEnv = env
        end
    end
end

