function OverseaManageCookingListMainDialog:GetShowDataByType()
    local showData = {}
    ---料理制作
    if self.type == MaidCoffeeConstants.CookingType.Cooking  then
        showData = self:GetSortShowData()
    ---外卖  要从外部传进来
    elseif self.type == MaidCoffeeConstants.CookingType.TakeOut or self.type == MaidCoffeeConstants.CookingType.VipOrder then
        showData = self:GetTakeOutData()
    else
        printError("不存在的类型。。。。。。")
    end
    return showData
end

function OverseaManageCookingListMainDialog:GetSortShowData()
    local showData = MaidCoffeeMgr:GetInstance():GetCookingShowVos(self.tabIndex)
    local t1 = {}
    local t2 = {}
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    for i, v in pairs(showData) do
        local recipeDojo = maidCoffeePlayerComponent:GetRecipeDoJoById(v.refId)
        ---解锁的放t1
        if recipeDojo then
            table.insert(t1,v)
        else
            table.insert(t2,v)
        end
    end
    table.sort(t1,function(a,b)
        local recipeDojoA = maidCoffeePlayerComponent:GetRecipeDoJoById(a.refId)
        local recipeDojoB = maidCoffeePlayerComponent:GetRecipeDoJoById(b.refId)
        if recipeDojoA.isCollect == recipeDojoB.isCollect then
            local canMakeA = self:CanMake(a)
            local canMakeB = self:CanMake(b)
            if canMakeA == canMakeB then
                if recipeDojoA.rating == recipeDojoB.rating then
                    if a.sort == b.sort then
                        return a.refId < b.refId
                    else
                        return a.sort < b.sort
                    end
                else
                    return recipeDojoA.rating > recipeDojoB.rating
                end
            else
                return canMakeA > canMakeB
            end
        else
            return recipeDojoA.isCollect > recipeDojoB.isCollect
        end
    end)

    table.sort(t2,function(a,b)
        local canGetA = self:IsCanGet(a)
        local canGetB = self:IsCanGet(b)
        if canGetA == canGetB then
            if a.sort == b.sort then
                return a.refId < b.refId
            else
                return a.sort < b.sort
            end
        else
            return canGetA > canGetB
        end
    end)
    table.insertto(t1,t2)
    return t1
end

function OverseaManageCookingListMainDialog:IsCanGet(data)
    local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.refId)
    if not isNull(foodVo) then
        if isSet(foodVo, "jumpAway") and table.count(foodVo.jumpAway) > 0 then
            local goodsConfMgr = GoodsConfMgr:GetInstance()
            local row = goodsConfMgr:GetJumpModuleRow(foodVo.jumpAway[1])
            if isSet(foodVo,"jumpParameter") then
                local type = GoodsUtils.GetIdType(foodVo.jumpParameter[1], Constants.IDArea.Quests)
                if type == Constants.IDType.QuestRegion then
                    local isUnLock =  ActionUtils.IsUnlockRegionQuest(foodVo.jumpParameter[1])
                    local mapVo = CfUtils.GetCfVo(AutoIds.IdSetting3022, "RegionQuestVo", foodVo.jumpParameter[1])
                    local teamPower = GameUtils.GetHistoryTeamPower()
                    local IsCanGet = isUnLock and teamPower >= mapVo.proposalLevel
                    return IsCanGet and 1 or 0
                else
                    local canJump = goodsConfMgr:CheckIsCanJump(row,false)
                    return canJump and 1 or 0
                end
            else
                local canJump = goodsConfMgr:CheckIsCanJump(row,false)
                return canJump and 1 or 0
            end
        else
            return 0
        end
    end
    return 0
end

function OverseaManageCookingListMainDialog:CanMake(data)
    local count = #data.foodStuff
    local index = 0
    for i = 1, count do
        local haveNum = GoodsUtils.GetThingNo(data.foodStuff[i])
        local needNum = tonumber(data.foodStuffNum[i])
        if haveNum >= needNum then
            index = index + 1
        end
    end
    return index == count and 1 or 0
end

function OverseaManageCookingListMainDialog:GetTakeOutData()
    local data = self.parameters.data
    local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
    local tempData = {}
    for i, v in pairs(data) do
        local vo = MaidCoffeeUtils.GetRecipeMakeIDGroupData(v.goodsId)
        vo.takeOutNum = v.num
        table.insert(tempData,vo)
    end
    return tempData
end

function OverseaManageCookingListMainDialog:RefreshShow()
    self.showData = self:GetShowDataByType()
    local index = 0
    if self.preSelectId and self.type == MaidCoffeeConstants.CookingType.Cooking  then
        index = self:GetIndexById() - 1
        self.preSelectFood = self:GetIndexById()
        self.preSelectId = nil
    end

    if self.ScrollView then
        if not self.ScrollView.IsListViewInit then
            self.ScrollView:InitListView(#self.showData, Bind(self, self.OnRefreshCellIndex))
            self.ScrollView:MovePanelToItemIndex(index,0)
        else
            GameUtils.ReloadData(self.ScrollView, #self.showData)
            self.ScrollView:MovePanelToItemIndex(index,0)
        end
    end
end

function OverseaManageCookingListMainDialog:GetIndexById()
    if self.preSelectId then
        for i, v in pairs(self.showData) do
            if v.refId == tonumber(self.preSelectId) then
                return i
            end
        end
    end
    return 1
end

function OverseaManageCookingListMainDialog:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.showData then
        return
    end
    local cell = listView:NewListViewItem(ItemCell)
    local tableCellEnv = CfUtils.GetLuaScr(cell, LeftFoodCell)
    tableCellEnv:SetCallBackAndIndex(Bind(self,self.OnLeftFoodCellClick),index + 1)
    ---传false 表示锁定时 不屏蔽点击事件
    tableCellEnv:SetIsPopTip(true)
    tableCellEnv:RefreshUI(self.showData[index + 1])
    tableCellEnv:RefreshExp()
    tableCellEnv:RefreshCanMake()
    tableCellEnv:RefreshCanGet()
    if self.type == MaidCoffeeConstants.CookingType.TakeOut or self.type == MaidCoffeeConstants.CookingType.VipOrder then
        tableCellEnv:RefreshNumShow()
    end
    tableCellEnv:PreSelectFood(self.preSelectFood)
    tableCellEnv:CalculationExp(self.preSelectFood)

    return cell
end

function OverseaManageCookingListMainDialog:OnLeftFoodCellClick(index)
    self:FoodCellDoSell(index)
    self.preSelectFood = index
    ---刷新右边的面板
    self.curFood = self.showData[index]
    if self.type == MaidCoffeeConstants.CookingType.Cooking then
        local str = tostring(table.concat({self.tabIndex,"_",self.curFood.refId}))
        self.controller:SetExtraArgument(str)
    end

    self:PlayCellSwitchAni()
    self.rightPanelEnv:InitNum()
    self:RefreshRightPanelShow(self.curFood)
    self:SetPriceShow()
end

function OverseaManageCookingListMainDialog:PlayComeOnAni(index)
    if self.lastIndex == index then
        return
    end
    local lastIndex = self.lastIndex
    --self.ani:Play("OverseaManageCookingListMainDialog_BGNode_Idle")
    for _, animationState in pairs(self.BgSwitchAni) do
        if animationState.name == "OverseaManageCookingListMainDialog_BGNode_Switch" then
            animationState.time = 0
            animationState.enabled = false
            self.BgSwitchAni:Sample()
        end
    end
    self.BgSwitchAni:Play("OverseaManageCookingListMainDialog_BGNode_Switch")
    self:StopSwitchCo()
    self.switchCo = cs_coroutine.start(function()
        coroutine.yield(Yielders.GetWaitForSeconds(0.25))
        self.lastIndex = index
        KTool.SetActive(self["ImgBg_TH_tlt_"..lastIndex].gameObject,false)
        --KTool.SetActive(self["ImgBg_TH_jbj_"..lastIndex].gameObject,false)
        KTool.SetActive(self["ImgBg_TH_tlt_"..self.lastIndex].gameObject,true)
        --KTool.SetActive(self["ImgBg_TH_jbj_"..self.lastIndex].gameObject,true)
    end)

end

function OverseaManageCookingListMainDialog:StopSwitchCo()
    if self.switchCo then
        cs_coroutine.stop(self.switchCo)
        self.switchCo = nil
    end
end

function OverseaManageCookingListMainDialog:SetPriceShow()
    if self.tipsEnv then
        self.tipsEnv:RefreshShow(self.curFood)
    end
end

function OverseaManageCookingListMainDialog:FoodCellDoSell(index)
    if self.curFood ~= nil and self.preSelectFood ~= index then
        local cell = self.ScrollView:GetShownItemByItemIndex(self.preSelectFood - 1)
        self.curFood.cacheExp = nil
        self.curFood.curInputNum = nil
        if cell then
            local tableCellEnv = CfUtils.GetLuaScr(cell, LeftFoodCell)
            tableCellEnv:DoSelect()
            tableCellEnv:RefreshExp()
        end
    end
end

function OverseaManageCookingListMainDialog:RefreshRightPanelShow(data)
    self.rightPanelEnv:ShowRightInfo(data)
end

function OverseaManageCookingListMainDialog:OnLevelUpSuccess(levelUpType)
    if levelUpType == Constants.UICultivateLevelUpFinishType.MaidCoffeeRecipeRatingUp then
        self.rightPanelEnv:InitNum()
        local cell = self.ScrollView:GetShownItemByItemIndex(self.preSelectFood - 1)
        if cell then
            local tableCellEnv = CfUtils.GetLuaScr(cell, LeftFoodCell)
            if tableCellEnv then
                tableCellEnv:RefreshExp()
            end
        end
        self:RefreshRightPanelShow(self.curFood)
    end
end

function OverseaManageCookingListMainDialog:__delete()
    self.controller = nil
    self.cookTypeEvn = nil
    self.preSelectTab = nil
    self.preSelectFood = nil
    self.rightPanelEnv = nil
    self.tipsEnv = nil
    self.curFood = nil
    self.lastIndex = nil
    Events.RemoveListener(Constants.EventNames.QuitLevelUpFinishDialog, self.onLevelUpEvent)
    self.onLevelUpEvent = nil
end

function OverseaManageCookingListMainDialog:OnBtnExplainClick()
    -- 计算targetNode在UI坐标系里的坐标
    local cam = UIModule.RootCanvas.defaultCamera
    local topLayerRt = UIModule.RootCanvas.transform:GetComponent("RectTransform")
    local screenPoint = CS.UnityEngine.RectTransformUtility.WorldToScreenPoint(cam, self.BtnExplain.transform.position)
    local isSuccess, targetNodeUIPos = CS.UnityEngine.RectTransformUtility.ScreenPointToLocalPointInRectangle(topLayerRt, screenPoint, cam)
    local content = self.TipNode.transform:Find("Root/Content").transform
    content.localPosition = Vector3.New(targetNodeUIPos.x, content.localPosition.y, 0)
    KTool.SetActive(self.TipNode.gameObject,not self.TipNode.gameObject.activeSelf)
end

function OverseaManageCookingListMainDialog:OnBtnRecommendRecipeClick()
    local skillId = self:GetSkillIdByType()
    if not isNull(skillId) then
        GameUtils.ShowCommonRecipeTips(self.BtnRecommend.gameObject,skillId)
    end
end

function OverseaManageCookingListMainDialog:GetSkillIdByType()
    local allVos =  CfUtils.GetCf(AutoIds.IdSetting4103, "MaidCoffeeRecipeSkillVo", true)
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local isCafeMax = maidCoffeePlayerComponent:IsToMaxCafeLevel()
    for i, v in pairs(allVos) do
        local type = isCafeMax and v.typeMax or v.type
        for _, j in pairs(type) do
            if tonumber(j) == self.tabIndex then
                return v.id
            end
        end
    end
    return nil
end

return OverseaManageCookingListMainDialog